-- Seed Lesson Assignments
SELECT gen_random_uuid(), l.id, v.title, v.instructions, v.max_score
FROM (VALUES
    ('go-golang-microservices-masterclass', 2, 3, 'Build a Resilient REST API with Fiber & Postgres', 'Create a production-ready HTTP REST API in Go using Fiber. Implement health checks, structured zap logging, connection pooling with sqlx, and graceful shutdown on SIGINT/SIGTERM. Submit your GitHub repository URL.', 100),
    ('go-golang-microservices-masterclass', 4, 3, 'Implement a Bidirectional gRPC Streaming Service', 'Define a protobuf contract with client and server streaming methods. Write a Go gRPC server and test client with interceptors for auth token propagation. Submit your GitHub repository URL.', 100),
    ('fullstack-nextjs-react-mastery', 1, 3, 'Build Next.js 15 App with Server Actions & Optimistic UI', 'Create an interactive task manager using Server Components, Server Actions, useOptimistic for instant UI feedback, and Postgres persistence. Submit your deployed Vercel link and GitHub repository URL.', 100),
    ('docker-kubernetes-modern-devops', 2, 3, 'Multi-Stage Dockerfile & Local Kubernetes Deployment', 'Write an optimized multi-stage Dockerfile (under 25MB runtime) for a Go or Node app. Create Kubernetes Deployment and Service manifests with liveness/readiness probes. Submit your manifests.', 100),
    ('python-data-science-machine-learning-bootcamp', 1, 3, 'Exploratory Data Analysis (EDA) on Real Estate Dataset', 'Clean missing values, detect outliers using IQR, generate correlation heatmaps with Seaborn, and build a baseline Linear Regression model. Submit your Jupyter Notebook (.ipynb).', 100),
    ('kubernetes-gitops-cilium-mastery', 1, 3, 'Cilium NetworkPolicy Zero-Trust Enforcement Lab', 'Deploy a three-tier microservice architecture. Author and apply CiliumNetworkPolicy resources that enforce strict layer-3 and layer-7 ingress/egress filtering. Submit your policy YAMLs.', 100)
) AS v(slug, ch_no, l_no, title, instructions, max_score)
JOIN courses c ON c.slug = v.slug
JOIN chapters ch ON ch.course_id = c.id AND ch.chapter_no = v.ch_no
JOIN lessons l ON l.chapter_id = ch.id AND l.lesson_no = v.l_no
ON CONFLICT (id) DO NOTHING;

